<section class="section product-detail"><div class="container"><div class="breadcrumb"><a href="<?php echo esc_url(get_post_type_archive_link('dms_product')); ?>"><?php echo esc_html(dms_t('Produk','Products')); ?></a><span>/</span><?php if ($terms && !is_wp_error($terms)) echo '<span>'.esc_html($terms[0]->name).'</span><span>/</span>'; ?><span><?php the_title(); ?></span></div><div class="product-detail__grid">
<div class="product-detail__media" data-reveal><?php dms_image_or_placeholder(get_the_ID(), 'large'); ?></div>
