</div></div></section>
<section class="section section--soft"><div class="container content-grid"><div><span class="eyebrow eyebrow--dark"><?php echo esc_html(dms_t('Gambaran Produk','Product Overview')); ?></span><h2><?php echo esc_html(dms_t('Dirancang untuk implementasi yang andal.','Designed for dependable implementation.')); ?></h2></div><div class="prose"><?php the_content(); ?></div></div></section>
